// Extract summary data
const summaryData = $('6. WayinVideo — Get Summary Results').item.json.data;

const summary = summaryData.summary || '';
const highlights = Array.isArray(summaryData.highlights)
  ? summaryData.highlights.map((h, i) => `${i + 1}. ${h.desc}`).join('\n')
  : '';
const tags = Array.isArray(summaryData.tags)
  ? summaryData.tags.join(', ')
  : '';

// Get sheet data
const videoUrl = $('2. Google Sheets — Read Pending Videos').item.json['Video URL'];
const videoTitle = $('2. Google Sheets — Read Pending Videos').item.json['Video Title'] || 'Untitled';
const newsletterNiche = $('2. Google Sheets — Read Pending Videos').item.json['Newsletter Niche / Brand'] || 'General';
const targetAudience = $('2. Google Sheets — Read Pending Videos').item.json['Target Audience'] || 'General audience';
const newsletterTone = $('2. Google Sheets — Read Pending Videos').item.json['Newsletter Tone'] || 'Educational';
const ctaLink = $('2. Google Sheets — Read Pending Videos').item.json['CTA Link'] || 'YOUR_LINK_HERE';

// Get current week number for issue numbering
const now = new Date();
const startOfYear = new Date(now.getFullYear(), 0, 1);
const weekNumber = Math.ceil(((now - startOfYear) / 86400000 + startOfYear.getDay() + 1) / 7);

return [{
  json: {
    summary,
    highlights,
    tags,
    videoUrl,
    videoTitle,
    newsletterNiche,
    targetAudience,
    newsletterTone,
    ctaLink,
    issueNumber: `Issue #${weekNumber} — ${now.getFullYear()}`
  }
}];

// Parse AI newsletter output
const output = $input.first().json.output || '';

// Extract each section
const subjectMatch = output.match(/SUBJECT_LINE:\s*([\s\S]*?)(?=\nPREVIEW_TEXT:|$)/);
const previewMatch = output.match(/PREVIEW_TEXT:\s*([\s\S]*?)(?=\nNEWSLETTER_INTRO:|$)/);
const introMatch = output.match(/NEWSLETTER_INTRO:\s*([\s\S]*?)(?=\nSECTION_1_HEADING:|$)/);
const s1HeadMatch = output.match(/SECTION_1_HEADING:\s*([\s\S]*?)(?=\nSECTION_1_BODY:|$)/);
const s1BodyMatch = output.match(/SECTION_1_BODY:\s*([\s\S]*?)(?=\nSECTION_2_HEADING:|$)/);
const s2HeadMatch = output.match(/SECTION_2_HEADING:\s*([\s\S]*?)(?=\nSECTION_2_BODY:|$)/);
const s2BodyMatch = output.match(/SECTION_2_BODY:\s*([\s\S]*?)(?=\nSECTION_3_HEADING:|$)/);
const s3HeadMatch = output.match(/SECTION_3_HEADING:\s*([\s\S]*?)(?=\nSECTION_3_BODY:|$)/);
const s3BodyMatch = output.match(/SECTION_3_BODY:\s*([\s\S]*?)(?=\nFEATURED_QUOTE:|$)/);
const quoteMatch = output.match(/FEATURED_QUOTE:\s*([\s\S]*?)(?=\nCTA_TEXT:|$)/);
const ctaTextMatch = output.match(/CTA_TEXT:\s*([\s\S]*?)(?=\nHASHTAGS:|$)/);
const hashtagsMatch = output.match(/HASHTAGS:\s*([\s\S]*)$/);

const subjectLine = subjectMatch ? subjectMatch[1].trim() : '';
const previewText = previewMatch ? previewMatch[1].trim() : '';
const intro = introMatch ? introMatch[1].trim() : '';
const s1Heading = s1HeadMatch ? s1HeadMatch[1].trim() : '';
const s1Body = s1BodyMatch ? s1BodyMatch[1].trim() : '';
const s2Heading = s2HeadMatch ? s2HeadMatch[1].trim() : '';
const s2Body = s2BodyMatch ? s2BodyMatch[1].trim() : '';
const s3Heading = s3HeadMatch ? s3HeadMatch[1].trim() : '';
const s3Body = s3BodyMatch ? s3BodyMatch[1].trim() : '';
const featuredQuote = quoteMatch ? quoteMatch[1].trim() : '';
const ctaText = ctaTextMatch ? ctaTextMatch[1].trim() : 'Watch Now';
const hashtags = hashtagsMatch ? hashtagsMatch[1].trim() : '';

// Build full newsletter body
const newsletterBody = [
  intro,
  '',
  `## ${s1Heading}`,
  s1Body,
  '',
  `## ${s2Heading}`,
  s2Body,
  '',
  `## ${s3Heading}`,
  s3Body,
  '',
  `> "${featuredQuote}"`,
  '',
  `[${ctaText}](${$('9. Code — Extract Summary Data').item.json.ctaLink})`
].join('\n');

const wordCount = newsletterBody.split(/\s+/).filter(w => w.length > 0).length;

if (!subjectLine || !intro) {
  throw new Error('Could not parse newsletter from AI output. Check the AI prompt format.');
}

const videoData = $('9. Code — Extract Summary Data').item.json;

return [{
  json: {
    subjectLine,
    previewText,
    newsletterBody,
    featuredQuote,
    ctaText,
    hashtags,
    wordCount,
    videoUrl: videoData.videoUrl,
    videoTitle: videoData.videoTitle,
    newsletterNiche: videoData.newsletterNiche,
    issueNumber: videoData.issueNumber,
    ctaLink: videoData.ctaLink
  }
}];
